package zone.moddev.mc.ironagearchitecture.probe;

import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.*;
import net.minecraft.entity.player.*;
import net.minecraft.init.Blocks;
import net.minecraft.item.ItemStack;
import net.minecraft.inventory.ClickType;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.*;
import net.minecraftforge.common.util.FakePlayerFactory;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import zone.moddev.mc.ironagearchitecture.*;
import zone.moddev.mc.ironagearchitecture.block.*;
import zone.moddev.mc.ironagearchitecture.roof.*;
import zone.moddev.mc.ironagearchitecture.client.*;

/** Exercises the real container and GUI packets, then builds the separate review scene. */
public final class WorkbenchClientProbe {
    private int phase,ticks,actions,coverIndex,capture;private BlockPos clickedCover;
    private Future<?> pending;
    private ArchitectWorkbench.Desk[] desks;
    private final List<BlockPos> coverAt=new ArrayList<>();
    private final List<String> shots=new ArrayList<>();
    private final Map<String,Object> result=new LinkedHashMap<>();
    private static void require(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END||phase==99)return;try{advance();}catch(Throwable failure){failure.printStackTrace();finish(failure.toString());}}
    private void advance()throws Exception {Minecraft mc=Minecraft.getMinecraft();ticks++;if(ticks%100==0)System.out.println("IAA_WORKBENCH_PHASE "+phase+" screen="+(mc.currentScreen==null?"world":mc.currentScreen.getClass().getName())+" pitch="+(WorkbenchClient.latest==null||WorkbenchClient.latest.plan==null?-1:WorkbenchClient.latest.plan.pitch)+" serverPitch="+(desks==null?-1:desks[0].drawing.pitch));if(ticks>(phase==15?coverAt.size()*6+500:500))throw new IllegalStateException("Workbench client timeout, phase="+phase);
        if(phase==0&&mc.currentScreen instanceof GuiMainMenu&&ticks>50){mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;String name=System.getProperty("iaa.previewName","Architect's Workbench Preview");require(!new java.io.File(mc.mcDataDir,"saves/"+name).exists(),"fresh preview world");mc.launchIntegratedServer(name,name,new WorldSettings(137,GameType.CREATIVE,false,false,WorldType.FLAT));next(1);return;}
        if(phase==1&&mc.player!=null){mc.displayGuiScreen(null);mc.gameSettings.hideGUI=false;pending=mc.getIntegratedServer().addScheduledTask(()->buildScene(mc));next(2);return;}
        if(phase==2&&done()&&ticks>30){teleport(mc,-33,16,-0.8,0,70);next(3);return;}
        if(phase==3&&ticks>20){BlockPos p=desks[0].getPos();teleport(mc,p.getX()+.5,p.getY(),p.getZ()-2,0,40);next(4);return;}
        if(phase==4&&ticks>15){BlockPos p=desks[0].getPos();mc.playerController.processRightClickBlock(mc.player,mc.world,null,p,EnumFacing.UP,new Vec3d(p).addVector(.5,1,.5),EnumHand.MAIN_HAND);actions++;next(5);return;}
        if(phase==5&&mc.currentScreen instanceof WorkbenchClient.Screen&&WorkbenchClient.latest!=null&&WorkbenchClient.latest.plan!=null&&ticks>15){require(WorkbenchClient.latest.plan.valid(),WorkbenchClient.latest.plan.error);press(mc,3);next(6);return;}
        if(phase==6&&ticks>12&&WorkbenchClient.latest.preview){press(mc,10);next(7);return;}
        if(phase==7&&ticks>18&&WorkbenchClient.latest.plan.pitch==0){press(mc,13);next(8);return;}
        if(phase==8&&ticks>18&&WorkbenchClient.latest.plan.base==1){capture(mc,"01-workbench-planning.png");mc.player.closeScreen();camera(mc,-40,24,-8,-32,18,5);next(80);return;}
        if(phase==80&&ticks>35){capture(mc,"02-ghost-frame.png");BlockPos p=desks[0].getPos();mc.gameSettings.hideGUI=false;teleport(mc,p.getX()+.5,p.getY(),p.getZ()-2,0,40);next(81);return;}
        if(phase==81&&ticks>15){BlockPos p=desks[0].getPos();mc.playerController.processRightClickBlock(mc.player,mc.world,null,p,EnumFacing.UP,new Vec3d(p).addVector(.5,1,.5),EnumHand.MAIN_HAND);next(82);return;}
        if(phase==82&&ticks>15&&mc.currentScreen instanceof WorkbenchClient.Screen){next(9);return;}
        if(phase==9&&ticks>15){require(!WorkbenchClient.latest.canBuild,"GUI disables construction without supplies");pending=mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP p=serverPlayer(mc);int cost=RoofConstruction.required(desks[0],desks[0].drawing);for(int i=0;i<9&&cost>0;i++){int count=Math.min(cost,64);p.inventory.setInventorySlotContents(9+i,new ItemStack(ArchitectureBlocks.ROOF_TIMBER,count,0));cost-=count;}p.openContainer.detectAndSendChanges();});next(10);return;}
        if(phase==10&&done()&&ticks>15){for(int i=27;i<36;i++)if(mc.player.openContainer.getSlot(i).getHasStack()){mc.playerController.windowClick(mc.player.openContainer.windowId,i,0,ClickType.QUICK_MOVE,mc.player);actions++;}next(11);return;}
        if(phase==11&&ticks>15){press(mc,4);next(12);return;}
        if(phase==12&&ticks>20&&!desks[0].active&&desks[0].index>0){require(desks[0].index==desks[0].operations.size(),"first GUI construction completed");mc.player.closeScreen();camera(mc,-40,23,-10,-32,18,4);next(13);return;}
        if(phase==13&&ticks>45){capture(mc,"02-first-frame.png");pending=mc.getIntegratedServer().addScheduledTask(()->startOtherFrames(mc));next(14);return;}
        if(phase==14&&done()&&ticks>30&&!desks[1].active&&!desks[2].active){pending=mc.getIntegratedServer().addScheduledTask(()->{for(int i=1;i<3;i++){Set<Long> columns=new HashSet<>();for(Map.Entry<Long,RoofCell> e:desks[i].drawing.cells.entrySet())if(e.getValue().timber()&&e.getValue().coverable()&&columns.add(RoofPlan.column(BlockPos.fromLong(e.getKey()).getX(),BlockPos.fromLong(e.getKey()).getZ())))coverAt.add(BlockPos.fromLong(e.getKey()));}});next(15);return;}
        if(phase==15&&done()){if(coverIndex<coverAt.size()){BlockPos at=coverAt.get(coverIndex++);pending=mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP builder=FakePlayerFactory.getMinecraft(mc.getIntegratedServer().worldServerForDimension(0));builder.capabilities.isCreativeMode=true;builder.setPosition(30,30,-20);ItemStack cover=RoofConstruction.coverItem(at.getX()<-5?1:2);RoofConstruction.cover(builder.world,at,builder,cover,EnumHand.MAIN_HAND);});return;}BlockPos p=desks[0].getPos();teleport(mc,p.getX()+.5,p.getY()+1.4,p.getZ()-2,0,40);next(16);return;}
        if(phase==16&&ticks>15){BlockPos p=desks[0].getPos();mc.playerController.processRightClickBlock(mc.player,mc.world,null,p,EnumFacing.UP,new Vec3d(p).addVector(.5,1,.5),EnumHand.MAIN_HAND);next(17);return;}
        if(phase==17&&ticks>15&&mc.currentScreen instanceof WorkbenchClient.Screen){press(mc,11);next(18);return;}
        if(phase==18&&ticks>18&&WorkbenchClient.latest.plan.pitch==1){pending=mc.getIntegratedServer().addScheduledTask(()->{int cost=RoofConstruction.required(desks[0],desks[0].drawing);for(int i=0;i<27&&cost>0;i++){int n=Math.min(cost,64);desks[0].give(new ItemStack(ArchitectureBlocks.ROOF_TIMBER,n,0));cost-=n;}serverPlayer(mc).openContainer.detectAndSendChanges();});next(19);return;}
        if(phase==19&&done()&&ticks>15){press(mc,3);next(20);return;}
        if(phase==20&&ticks>12){capture(mc,"03-revised-drawing.png");press(mc,4);next(21);return;}
        if(phase==21&&ticks>20&&!desks[0].active&&desks[0].drawing.pitch==1){mc.player.closeScreen();pending=mc.getIntegratedServer().addScheduledTask(()->finishScene(mc));next(22);return;}
        if(phase==22&&done()&&ticks>60){verifyModels(mc);prepareClick(mc);next(30);return;}
        if(phase==30&&done()&&ticks>15){Vec3d eye=SmartThatchBlock.eyes(mc.player),look=SmartThatchBlock.look(mc.player);net.minecraft.util.math.RayTraceResult hit=mc.world.rayTraceBlocks(eye,eye.add(look.scale(5)),false,false,false);require(hit!=null&&mc.world.getBlockState(hit.getBlockPos()).getBlock() instanceof RoofFrameBlock,"actual cover ray hits frame");clickedCover=hit.getBlockPos();require(mc.player.getHeldItemMainhand()!=null,"cover item synchronized");EnumActionResult action=mc.playerController.processRightClickBlock(mc.player,mc.world,mc.player.getHeldItemMainhand(),clickedCover,hit.sideHit,hit.hitVec,EnumHand.MAIN_HAND);require(action==EnumActionResult.SUCCESS,"native covering click accepted");actions++;next(31);return;}
        if(phase==31&&ticks>15&&RoofFrameBlock.cover(mc.world.getBlockState(clickedCover))==3){pending=mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP p=serverPlayer(mc);require(p.getHeldItemMainhand()!=null&&p.getHeldItemMainhand().stackSize==63,"one clay tile consumed through real player packet");p.setGameType(GameType.CREATIVE);p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();p.inventory.setInventorySlotContents(0,new ItemStack(ArchitectureBlocks.ARCHITECTS_WORKBENCH));result.put("nativeCoverClick",true);});next(32);return;}
        if(phase==32&&done()&&ticks>15){verifyModels(mc);next(23);return;}
        if(phase==23){double[][] views={{-21,18,-19,-17,16,4},{-39,22,-8,-32,18,4},{-35,17,2,-32,20,7},{-12,33,-1,-16,17,5},{-17,16,4,-16,19,6},{8,22,-7,1,18,4}};if(capture>=views.length){finish("");return;}double[] v=views[capture];camera(mc,v[0],v[1],v[2],v[3],v[4],v[5]);next(24);return;}
        if(phase==24&&ticks>45){capture(mc,new String[]{"04-street.png","05-bare-frame.png","06-attic-interior.png","07-roof-overhead.png","08-thatch-underside.png","09-slate-roof.png"}[capture++]);next(23);}
    }
    private void next(int p){System.out.println("IAA_WORKBENCH_PHASE_ENTER "+p);phase=p;ticks=0;}
    private boolean done()throws Exception {if(pending==null)return true;if(!pending.isDone())return false;pending.get();pending=null;return true;}
    private static EntityPlayerMP serverPlayer(Minecraft mc){return mc.getIntegratedServer().getPlayerList().getPlayerByUUID(mc.player.getUniqueID());}
    private void buildScene(Minecraft mc){WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);w.setWorldTime(6000);w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");w.getGameRules().setOrCreateGameRule("doWeatherCycle","false");desks=new ArchitectWorkbench.Desk[3];for(int x=-48;x<16;x++)for(int z=-18;z<18;z++){for(int y=4;y<10;y++)w.setBlockState(new BlockPos(x,y,z),(y==9&&z<0?Blocks.GRAVEL:Blocks.DIRT).getDefaultState(),2);if(z>=0)w.setBlockState(new BlockPos(x,9,z),Blocks.GRASS.getDefaultState(),2);}
        for(int i=0;i<3;i++){int ox=-36+i*18;for(int x=ox;x<ox+8;x++)for(int z=0;z<11;z++){for(int y=10;y<40;y++)w.setBlockToAir(new BlockPos(x,y,z));w.setBlockState(new BlockPos(x,9,z),Blocks.STONEBRICK.getDefaultState(),2);if(x==ox||x==ox+7||z==0||z==10)for(int y=10;y<14;y++)w.setBlockState(new BlockPos(x,y,z),ArchitectureBlocks.SMART_COB.getStateFromMeta(i==1?0:1),2);w.setBlockState(new BlockPos(x,14,z),ArchitectureBlocks.findFloor(i==0?"oak":i==1?"spruce":"dark_oak",FloorShape.FULL,null).getDefaultState(),2);}BlockPos door=new BlockPos(ox+3,10,0);w.setBlockToAir(door);w.setBlockToAir(door.up());net.minecraft.item.ItemDoor.placeDoor(w,door,EnumFacing.NORTH,Blocks.SPRUCE_DOOR,false);if(ArchitectureConfig.windows)for(int x:new int[]{ox+1,ox+5})w.setBlockState(new BlockPos(x,11,0),ArchitectureBlocks.findWindow("dark_oak",1,false,true,false).getDefaultState().withProperty(WindowBlock.FACING,EnumFacing.NORTH),2);BlockPos bench=new BlockPos(ox+4,15,5);w.setBlockState(bench,ArchitectureBlocks.ARCHITECTS_WORKBENCH.getDefaultState(),3);desks[i]=(ArchitectWorkbench.Desk)w.getTileEntity(bench);RoofConstruction.detect(desks[i]);desks[i].drawing.version=1;RoofPlanner.solve(desks[i].drawing);}
        EntityPlayerMP p=serverPlayer(mc);p.setGameType(GameType.SURVIVAL);p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();w.setSpawnPoint(new BlockPos(-16,10,-9));ProbeShapes.flush(w);
    }
    private void startOtherFrames(Minecraft mc){EntityPlayerMP p=FakePlayerFactory.getMinecraft(mc.getIntegratedServer().worldServerForDimension(0));p.setPosition(25,30,25);p.capabilities.isCreativeMode=true;for(int i=1;i<3;i++){desks[i].drawing.pitch=i==1?1:2;desks[i].drawing.wood=i==1?1:5;desks[i].drawing.alongX=true;RoofPlanner.solve(desks[i].drawing);require(RoofConstruction.start(desks[i],p),desks[i].status);}}
    private void finishScene(Minecraft mc){WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);for(int i=1;i<3;i++){RoofPlan p=desks[i].drawing;double mid=(p.minZ+p.maxZ+1)/2.0;for(int x:new int[]{p.minX,p.maxX})for(int z=p.minZ;z<=p.maxZ;z++){double h=15.25+RoofPlan.PITCHES[p.pitch]*Math.min(z-p.minZ,p.maxZ+1-z);for(int y=15;y<Math.floor(h)-1;y++){BlockPos at=new BlockPos(x,y,z);if(w.isAirBlock(at))w.setBlockState(at,ArchitectureBlocks.SMART_COB.getStateFromMeta(i==1?0:1),2);}}}EntityPlayerMP player=serverPlayer(mc);player.setGameType(GameType.CREATIVE);player.capabilities.allowFlying=true;player.capabilities.isFlying=true;player.sendPlayerAbilities();player.inventory.setInventorySlotContents(0,new ItemStack(ArchitectureBlocks.ARCHITECTS_WORKBENCH));player.inventory.setInventorySlotContents(1,new ItemStack(ArchitectureBlocks.ROOF_TIMBER,64,0));player.inventory.setInventorySlotContents(2,new ItemStack(ArchitectureBlocks.SMART_THATCH,64));player.inventory.setInventorySlotContents(3,RoofConstruction.coverItem(2));player.inventory.setInventorySlotContents(4,RoofConstruction.coverItem(3));player.inventory.setInventorySlotContents(5,new ItemStack(ArchitectureBlocks.findFloor("oak",FloorShape.FULL,null),64));ProbeShapes.flush(w);try{w.saveAllChunks(true,null);}catch(net.minecraft.world.MinecraftException e){throw new IllegalStateException(e);}}
    private void prepareClick(Minecraft mc){RoofPlan p=desks[0].drawing;for(Map.Entry<Long,RoofCell> e:p.cells.entrySet()){BlockPos at=BlockPos.fromLong(e.getKey());RoofCell c=e.getValue();if(at.getX()!=p.minX+1||at.getZ()!=p.minZ-1||!c.timber()||!c.coverable())continue;for(RoofMeshes.Face face:RoofMeshes.get(c,0).faces){if(face.normal[1]<.5)continue;double[] centre=new double[3];for(double[] v:face.vertices)for(int i=0;i<3;i++)centre[i]+=v[i]/face.vertices.length;double tx=at.getX()+centre[0],ty=at.getY()+centre[1],tz=at.getZ()+centre[2],x=tx+face.normal[0]*2.5,y=ty+face.normal[1]*2.5-mc.player.getEyeHeight(),z=tz+face.normal[2]*2.5;float yaw=(float)(Math.toDegrees(Math.atan2(tz-z,tx-x))-90),pitch=(float)-Math.toDegrees(Math.atan2(ty-y-mc.player.getEyeHeight(),Math.hypot(tx-x,tz-z)));teleport(mc,x,y,z,yaw,pitch);pending=mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP actor=serverPlayer(mc);actor.setGameType(GameType.SURVIVAL);actor.capabilities.allowFlying=true;actor.capabilities.isFlying=true;actor.sendPlayerAbilities();actor.inventory.currentItem=0;ItemStack stack=RoofConstruction.coverItem(3);stack.stackSize=64;actor.inventory.setInventorySlotContents(0,stack);actor.inventoryContainer.detectAndSendChanges();});return;}}throw new IllegalStateException("No native roofing target");}
    private void verifyModels(Minecraft mc){int cells=0,faces=0;for(ArchitectWorkbench.Desk d:desks)for(Map.Entry<Long,RoofCell> e:d.drawing.cells.entrySet()){BlockPos at=BlockPos.fromLong(e.getKey());RoofCell client=RoofData.get(mc.world).at(mc.world,at);require(e.getValue().equals(client),"client roof descriptor mismatch "+at);net.minecraft.block.state.IBlockState s=mc.world.getBlockState(at);require(s.getBlock() instanceof RoofFrameBlock,"client frame state "+at);net.minecraft.client.renderer.block.model.IBakedModel model=mc.getBlockRendererDispatcher().getModelForState(s);require(model instanceof RoofFrameBakedModel,"native frame model "+at);java.util.List<net.minecraft.client.renderer.block.model.BakedQuad> q=model.getQuads(s.getBlock().getExtendedState(s,mc.world,at),null,0);require(q.size()==RoofMeshes.get(client,RoofFrameBlock.cover(s)).faces.size(),"native geometry count "+at);for(net.minecraft.client.renderer.block.model.BakedQuad quad:q)require(!quad.getSprite().getIconName().contains("missingno"),"missing frame sprite");faces+=q.size();cells++;}result.put("syncedCells",cells);result.put("renderedFaces",faces);result.put("guiActions",actions);}
    private void teleport(Minecraft mc,double x,double y,double z,float yaw,float pitch){mc.player.capabilities.allowFlying=true;mc.player.capabilities.isFlying=true;mc.player.motionX=mc.player.motionY=mc.player.motionZ=0;mc.player.setLocationAndAngles(x,y,z,yaw,pitch);mc.player.sendPlayerAbilities();mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP p=serverPlayer(mc);p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();p.connection.setPlayerLocation(x,y,z,yaw,pitch);});}
    private void camera(Minecraft mc,double x,double y,double z,double tx,double ty,double tz){mc.gameSettings.hideGUI=true;mc.displayGuiScreen(null);float yaw=(float)(Math.toDegrees(Math.atan2(tz-z,tx-x))-90),pitch=(float)-Math.toDegrees(Math.atan2(ty-y,Math.hypot(tx-x,tz-z)));teleport(mc,x,y,z,yaw,pitch);}
    private void press(Minecraft mc,int id)throws Exception {require(mc.currentScreen instanceof WorkbenchClient.Screen,"workbench GUI open");GuiButton chosen=null;for(java.lang.reflect.Field f:GuiScreen.class.getDeclaredFields())if(List.class.isAssignableFrom(f.getType())){f.setAccessible(true);Object value=f.get(mc.currentScreen);if(value instanceof List)for(Object entry:(List<?>)value)if(entry instanceof GuiButton&&((GuiButton)entry).id==id)chosen=(GuiButton)entry;}require(chosen!=null&&chosen.enabled,"GUI control "+id+" enabled");for(java.lang.reflect.Method m:WorkbenchClient.Screen.class.getDeclaredMethods())if(Arrays.equals(m.getParameterTypes(),new Class<?>[]{GuiButton.class})){m.setAccessible(true);m.invoke(mc.currentScreen,chosen);actions++;return;}throw new IllegalStateException("GUI action method missing");}
    private void capture(Minecraft mc,String name){net.minecraft.util.ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());shots.add(name);}
    private void finish(String error){if(phase==99)return;phase=99;Minecraft mc=Minecraft.getMinecraft();result.put("passed",error.isEmpty());result.put("error",error);if(!error.isEmpty())capture(mc,"failure-phase-"+phase+".png");result.put("screenshots",shots);result.put("runtimeSha256",System.getProperty("iaa.runtimeSha256"));try{Files.write(mc.mcDataDir.toPath().resolve("workbench-client.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new RuntimeException(e);}System.out.println("IAA_CLIENT_PROBE_"+(error.isEmpty()?"PASS":"FAIL")+" architectsWorkbench");mc.shutdown();}
}
